{
  "name": "IQ波形文件转换工具",
  "name_en": "IQ Waveform File Converter",
  "manufacturer": "Rohde & Schwarz",
  "description": "用于读写和打包 IQW、WV、IQ.tar 等 IQ 基带波形文件的软件工具，常用于实验室中矢量信号发生器或其他射频仪器的离线波形准备、数据交换与文件格式转换。",
  "description_en": "A software utility for reading, writing, and packaging IQ baseband waveform files such as IQW, WV, and IQ.tar. It is commonly used in laboratories for offline waveform preparation, data exchange, and file format conversion for vector signal generators and related RF instruments.",
  "tag_hints": [
    "IQ waveform files",
    "baseband I/Q data",
    "vector signal generator",
    "RF waveform preparation",
    "iq.tar",
    "IQW/WV formats"
  ],
  "actions": [
    {
      "action_name": "auto-writeIqw",
      "description": "写出 IQW 格式的 IQ 数据文件。",
      "description_en": "Write I/Q data to an IQW file."
    },
    {
      "action_name": "auto-readIqw",
      "description": "读取 IQW 格式的 IQ 数据文件。",
      "description_en": "Read I/Q data from an IQW file."
    },
    {
      "action_name": "auto-writeWv",
      "description": "写出 WV 格式的波形文件。",
      "description_en": "Write a waveform file in WV format."
    },
    {
      "action_name": "auto-readWv",
      "description": "读取 WV 格式的波形文件。",
      "description_en": "Read a waveform file in WV format."
    },
    {
      "action_name": "auto-writeXml",
      "description": "为 IQ.tar 数据包生成 XML 元数据文件。",
      "description_en": "Generate the XML metadata file for an IQ.tar package."
    },
    {
      "action_name": "auto-writeIqTar",
      "description": "写出 IQ.tar 格式的 IQ 数据包。",
      "description_en": "Write an I/Q data package in IQ.tar format."
    },
    {
      "action_name": "auto-readIqTar",
      "description": "读取 IQ.tar 格式的 IQ 数据包。",
      "description_en": "Read an I/Q data package from an IQ.tar file."
    },
    {
      "action_name": "auto-main",
      "description": "运行主流程。",
      "description_en": "Run the main workflow."
    }
  ]
}

